  "demo-p-2": {
    c: [
      [26, "\u9577\u8F29\u6234\u624B\u74B0\u6700\u5E38\u898B\u7684\u554F\u984C\u662F\u5FD8\u8A18\u5145\u96FB\uFF0C\u5145\u4E00\u6B21\u80FD\u6490\u591A\u4E45\uFF1F"],
      [22, "\u8DCC\u5012\u5075\u6E2C\u7684\u8AA4\u5831\u7387\u5F88\u91CD\u8981\uFF0C\u592A\u5E38\u8AA4\u5831\u5BB6\u4EBA\u5C31\u6703\u958B\u59CB\u5FFD\u7565\u901A\u77E5\u3002"]
    ]
  },
  "demo-p-3": {
    c: [
      [13, "\u5FAA\u74B0\u5305\u6750\u6700\u96E3\u7684\u662F\u56DE\u6536\u7387\uFF0C\u5305\u6750\u5BC4\u51FA\u53BB\u56DE\u4E0D\u4F86\uFF0C\u6210\u672C\u5C31\u6703\u58D3\u57AE\u6574\u500B\u6A21\u5F0F\u3002"],
      [24, "\u793E\u5340\u5718\u8CFC\u7684\u53D6\u8CA8\u9EDE\u53EF\u4EE5\u9806\u4FBF\u7576\u56DE\u6536\u7AD9\uFF0C\u6211\u5011\u5F88\u9858\u610F\u5408\u4F5C\u3002"],
      [14, "\u6709\u6C92\u6709\u7B97\u904E\u6BCF\u500B\u5305\u6750\u8981\u5FAA\u74B0\u5E7E\u6B21\u624D\u6BD4\u4E00\u6B21\u6027\u7D19\u7BB1\u74B0\u4FDD\uFF1F"]
    ]
  },
  "demo-p-4": {
    c: [
      [37, "\u540C\u6A23\u505A\u5132\u80FD\uFF0C\u793E\u5340\u578B\u6700\u5927\u7684\u6311\u6230\u662F\u4F4F\u6236\u4E4B\u9593\u7684\u96FB\u8CBB\u600E\u9EBC\u5206\u914D\uFF0C\u9019\u584A\u6F14\u7B97\u6CD5\u6709\u8003\u616E\u55CE\uFF1F"],
      [39, "\u7BA1\u59D4\u6703\u901A\u5E38\u5F88\u4FDD\u5B88\uFF0C\u5982\u679C\u6709\u8A66\u8FA6\u793E\u5340\u7684\u6578\u64DA\u6703\u6BD4\u8F03\u597D\u8AAA\u670D\u3002"]
    ]
  },
  "demo-p-5": {
    c: [
      [14, "\u6D77\u85FB\u5305\u6750\u7684\u6210\u672C\u8DDF\u4E00\u822C\u5851\u81A0\u5DEE\u591A\u5C11\uFF1F\u4F01\u696D\u63A1\u8CFC\u6700\u5728\u610F\u9019\u500B\u3002"],
      [8, "\u60F3\u554F\u5206\u89E3\u689D\u4EF6\u662F\u4E00\u822C\u63A9\u57CB\u5C31\u53EF\u4EE5\uFF0C\u9084\u662F\u9700\u8981\u5DE5\u696D\u5806\u80A5\uFF1F"],
      [18, "\u6211\u5011\u5BF5\u7269\u9BAE\u98DF\u7684\u5305\u88DD\u5F88\u9700\u8981\u9632\u6C34\u53C8\u53EF\u5206\u89E3\u7684\u6750\u8CEA\uFF0C\u6709\u6A23\u54C1\u53EF\u4EE5\u8A66\u55CE\uFF1F"]
    ]
  },
  "demo-p-6": {
    c: [
      [20, "\u504F\u9109\u5B78\u6821\u7684\u7DB2\u8DEF\u8DDF\u8A2D\u5099\u5DEE\u7570\u5F88\u5927\uFF0C\u5E73\u53F0\u80FD\u96E2\u7DDA\u4F7F\u7528\u55CE\uFF1F"],
      [30, "\u6211\u5011\u57FA\u91D1\u6703\u6709\u5728\u504F\u9109\u8AB2\u8F14\uFF0C\u5F88\u60F3\u8A66\u7528\u770B\u770B\uFF01"],
      [12, "\u81EA\u9069\u61C9\u5B78\u7FD2\u5F88\u597D\uFF0C\u4F46\u5C0F\u670B\u53CB\u4E5F\u9700\u8981\u6709\u4EBA\u966A\uFF0C\u5EFA\u8B70\u642D\u914D\u7DDA\u4E0A\u966A\u8B80\u5FD7\u5DE5\u3002"]
    ]
  }
